func (dayWhere[Q]) AliasedAs(alias string) dayWhere[Q] {
	return buildDayWhere[Q](buildDayColumns(alias))
}

func buildDayWhere[Q sqlite.Filterable](cols dayColumns) dayWhere[Q] {
	return dayWhere[Q]{
		cols: cols,
		ID:   sqlite.Where[Q, int64](cols.ID.Expression),
		Date: sqlite.Where[Q, time.Time](cols.Date.Expression),
		R:    dayWhereR[Q]{cols: cols},
	}
}

// dayWhereR holds the relationship-based filters of
// dayWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type dayWhereR[Q sqlite.Filterable] struct {
	cols dayColumns
}

// HasDeepWorkLogs filters parents that have a matching DeepWorkLogs using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to DeepWorkLogs).
func (w dayWhereR[Q]) HasDeepWorkLogs(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(DeepWorkLogs.NameExpr()),
		sm.Where(DeepWorkLogs.Columns.DayID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

