type dayJoins[Q dialect.Joinable] struct {
	typ          string
	DeepWorkLogs modAs[Q, deepWorkLogColumns]
	FitnessLogs  modAs[Q, fitnessLogColumns]
	Habits       modAs[Q, habitColumns]
	SleepLogs    modAs[Q, sleepLogColumns]
}

func (j dayJoins[Q]) aliasedAs(alias string) dayJoins[Q] {
	return buildDayJoins[Q](buildDayColumns(alias), j.typ)
}

func buildDayJoins[Q dialect.Joinable](cols dayColumns, typ string) dayJoins[Q] {
	return dayJoins[Q]{
		typ: typ,
		DeepWorkLogs: modAs[Q, deepWorkLogColumns]{
			c: DeepWorkLogs.Columns,
			f: func(to deepWorkLogColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, DeepWorkLogs.NameExpr().As(to.Alias())).On(
						to.DayID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		FitnessLogs: modAs[Q, fitnessLogColumns]{
			c: FitnessLogs.Columns,
			f: func(to fitnessLogColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, FitnessLogs.NameExpr().As(to.Alias())).On(
						to.DayID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Habits: modAs[Q, habitColumns]{
			c: Habits.Columns,
			f: func(to habitColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Habits.NameExpr().As(to.Alias())).On(
						to.DayID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		SleepLogs: modAs[Q, sleepLogColumns]{
			c: SleepLogs.Columns,
			f: func(to sleepLogColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SleepLogs.NameExpr().As(to.Alias())).On(
						to.DayID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
